"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisFooterContent } from "./components/footer-sections/content";
import View5 from "./components/footer-sections/variants/06-frame";
const variants = {"frame":View5};
export type { ArtemisFooterClock, ArtemisFooterColumn, ArtemisFooterColumnLink, ArtemisFooterContent, ArtemisFooterImage, ArtemisFooterLink, ArtemisFooterNewsletter, ArtemisFooterSocialLink } from "./components/footer-sections/content";
export interface ArtemisFooterSectionsProps { className?: string; variant?: "frame"; /** The words on the footer; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisFooterContent>; }
export function ArtemisFooterSections({ className, variant = "frame", content }: ArtemisFooterSectionsProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link, and where it goes. Links to other sites (http or https) open in a new tab. */
export interface ArtemisFooterLink {
  label: string;
  href: string;
}

/** A link in a column. */
export interface ArtemisFooterColumnLink extends ArtemisFooterLink {
  /** Shows the link in the stronger style, for a "browse all" link. landscape. */
  highlight?: boolean;
}

/** A small heading over a list of links. */
export interface ArtemisFooterColumn {
  title: string;
  links: ArtemisFooterColumnLink[];
}

/** A profile or contact link drawn as an icon. Its label names the link for screen readers, and is its tooltip where the layout has one. */
export interface ArtemisFooterSocialLink extends ArtemisFooterLink {
  /** The icon. Without one, the link keeps the icon the layout draws in that position. */
  icon?: ComponentType<{ className?: string }>;
}

/** A picture, and the words that describe it. */
export interface ArtemisFooterImage {
  src: string;
  alt: string;
}

/** An email sign-up form. */
export interface ArtemisFooterNewsletter {
  /** The heading over the form. */
  title: string;
  /** A line under the heading. */
  text: string;
  /** Sample text in the empty email field. */
  placeholder: string;
  /** The button. */
  button: string;
  /** The button while the address is being sent. */
  sending: string;
  /** The button once the address is sent. */
  sent: string;
}

/** A live clock for one city. */
export interface ArtemisFooterClock {
  /** The city named beside the clock face. */
  city: string;
  /** The city's IANA time zone, such as "Europe/Copenhagen". The clock stays blank if the zone is unknown. */
  timeZone: string;
  /** A line over the time. */
  caption: string;
}

/** The words on an Artemis footer. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisFooterContent {
  /** The name beside the logo mark, and where it links. All layouts; wordmark, spotlight and mega show the name without a link, and wordmark and spotlight also draw it large across the foot. */
  brand: ArtemisFooterLink;
  /** A sentence about the brand. landscape, studio, local-time, frame, spotlight, mega and cta. */
  tagline?: string;
  /** The footer's main line. panorama and wordmark show it as a heading, landscape as a line under `tagline`, studio as a line over `cta`. */
  headline?: string;
  /** The styled end of the headline. It goes with `headline`: give `headline` alone and it shows alone, give both and both show. panorama, wordmark and landscape style it; studio runs it on after `headline`. */
  headlineAccent?: string;
  /** A paragraph under the headline. panorama. */
  subhead?: string;
  /** The main link. panorama and wordmark show it as a button, studio as a large underlined link. */
  cta?: ArtemisFooterLink;
  /** A quieter button beside `cta`. panorama. */
  secondaryCta?: ArtemisFooterLink;
  /** A short status, such as availability. studio and mega show it in a pill with a dot. */
  status?: string;
  /** A picture. panorama shows it wide; studio shows it over `location`. */
  image?: ArtemisFooterImage;
  /** Where you are, beside a map pin. studio. */
  location?: string;
  /** A row of links without headings. panorama and studio, which list the links of `columns` instead when you give only those. */
  links?: ArtemisFooterLink[];
  /** Columns of links under small headings. wordmark, landscape, local-time, frame, spotlight, mega and cta. */
  columns?: ArtemisFooterColumn[];
  /** An email sign-up form. mega. */
  newsletter?: ArtemisFooterNewsletter;
  /** A live clock for one city. local-time. */
  clock?: ArtemisFooterClock;
  /** Icon links to profiles or email. panorama, landscape, studio, frame, mega and cta. */
  social?: ArtemisFooterSocialLink[];
  /** The copyright line. All layouts but landscape. */
  legal?: string;
  /** Small links beside the copyright line. panorama, studio, local-time, frame and cta. */
  legalLinks?: ArtemisFooterLink[];
  /** A short closing line near the copyright. wordmark, frame and spotlight. */
  note?: string;
}

"use client";
// @zeus-internal
import { MotionConfig, motion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import type { ArtemisFooterContent, ArtemisFooterSocialLink } from "../content";
const CARD_HIDDEN = { opacity: 0, y: 16 } as const;
const CARD_SHOWN = { opacity: 1, y: 0 } as const;
const CARD_REVEAL = { duration: 0.55, ease: ARTEMIS_EASE_OUT } as const;
const DEFAULT = {
    brand: { label: "Workspace", href: "/" },
    tagline: "A calmer place to plan your work and keep good ideas moving.",
    columns: [
        { title: "Workspace", links: [{ label: "Projects", href: "/projects" }, { label: "Team spaces", href: "/teams" }, { label: "Integrations", href: "/integrations" }, { label: "Plans & pricing", href: "/pricing" }] },
        { title: "Discover", links: [{ label: "Our story", href: "/about" }, { label: "Customer stories", href: "/customers" }, { label: "What\u2019s new", href: "/changelog" }, { label: "Journal", href: "/journal" }, { label: "Careers", href: "/careers" }] },
        { title: "Support", links: [{ label: "Getting started", href: "/docs" }, { label: "Help center", href: "/help" }, { label: "Community", href: "/community" }, { label: "Contact us", href: "mailto:hello@example.com" }] },
    ],
    legal: "\u00A9 2026 Workspace",
    legalLinks: [{ label: "Privacy", href: "/privacy" }, { label: "Terms", href: "/terms" }, { label: "Accessibility", href: "/accessibility" }],
    note: "Made for a little more focus.",
    social: [{ label: "GitHub", href: "https://github.com" }],
} satisfies ArtemisFooterContent;
/** The layout's own icons in order, for social links that come without one. */
const SOCIAL_ICONS = [
    <svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor" className="art:size-4">
      <path d="M12 1a11 11 0 0 0-3.48 21.44c.55.1.75-.24.75-.53v-1.87c-3.06.67-3.71-1.47-3.71-1.47-.5-1.28-1.22-1.62-1.22-1.62-1-.68.07-.67.07-.67 1.11.08 1.69 1.14 1.69 1.14.98 1.69 2.58 1.2 3.21.92.1-.71.39-1.2.7-1.48-2.44-.28-5.01-1.22-5.01-5.43 0-1.2.43-2.18 1.13-2.95-.11-.28-.49-1.4.11-2.9 0 0 .92-.3 3.02 1.12a10.4 10.4 0 0 1 5.5 0c2.1-1.42 3.02-1.12 3.02-1.12.6 1.5.22 2.62.11 2.9.7.77 1.13 1.75 1.13 2.95 0 4.22-2.58 5.15-5.03 5.42.4.35.75 1.03.75 2.08v3.08c0 .3.2.64.76.53A11 11 0 0 0 12 1z"/>
    </svg>,
];
/** Links to other sites open in a new tab. */
const newTab = (href: string) => (/^https?:/.test(href) ? { target: "_blank", rel: "noreferrer noopener" } : {});
export default function FooterSectionsFrame({ content }: { content?: Partial<ArtemisFooterContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const social: ArtemisFooterSocialLink[] = copy.social;
    return (<MotionConfig reducedMotion="user">
      <footer className="art:relative art:isolate art:w-full art:overflow-hidden art:p-3 art:text-foreground art:@min-[640px]/artemis:p-5 art:@min-[1024px]/artemis:p-8">
        <div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-0 art:-z-10 art:bg-[linear-gradient(115deg,#b7d3ec_0%,#e6edf7_45%,#b3e8d9_100%)] art:dark:opacity-40"/>
        <div aria-hidden="true" className="art:pointer-events-none art:absolute art:-left-1/4 art:-top-full art:-z-10 art:h-[180%] art:w-[150%] art:rotate-12 art:rounded-full art:bg-background/25"/>
        <motion.div className="art:mx-auto art:max-w-7xl art:rounded-3xl art:bg-background art:px-6 art:pt-8 art:@min-[640px]/artemis:px-10 art:@min-[640px]/artemis:pt-10 art:@min-[1024px]/artemis:px-12 art:@min-[1024px]/artemis:pt-12" initial={CARD_HIDDEN} whileInView={CARD_SHOWN} viewport={{ once: true, amount: 0.1 }} transition={CARD_REVEAL}>
          <div className="art:grid art:gap-10 art:pb-10 art:@min-[1024px]/artemis:grid-cols-[1.2fr_2.8fr] art:@min-[1024px]/artemis:gap-16 art:@min-[1024px]/artemis:pb-12">
            <div>
              <a href={copy.brand.href} {...newTab(copy.brand.href)} className="art:inline-flex art:min-h-10 art:items-center art:gap-3 art:rounded-full art:text-xl art:font-medium art:tracking-tight art:focus-visible:outline-2 art:focus-visible:outline-offset-4 art:focus-visible:outline-ring">
                <span aria-hidden="true" className="art:text-primary">
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-orbit art:size-7" aria-hidden="true">
                    <path d="M20.341 6.484A10 10 0 0 1 10.266 21.85"/>
                    <path d="M3.659 17.516A10 10 0 0 1 13.74 2.152"/>
                    <circle cx="12" cy="12" r="3"/>
                    <circle cx="19" cy="5" r="2"/>
                    <circle cx="5" cy="19" r="2"/>
                  </svg>
                </span>
                {copy.brand.label}
              </a>
              <p className="art:mt-4 art:max-w-xs art:text-sm art:leading-6 art:text-muted-foreground">
                {copy.tagline}
              </p>
            </div>
            <div className="art:grid art:grid-cols-2 art:gap-x-6 art:gap-y-8 art:@min-[640px]/artemis:grid-cols-3 art:@min-[640px]/artemis:gap-x-10">
              {copy.columns.map((column, index) => <nav key={index} aria-label={column.title}>
                <h2 className="art:mb-3 art:text-xs art:font-medium art:uppercase art:tracking-wider art:text-muted-foreground">
                  {column.title}
                </h2>
                <ul>
                  {column.links.map((link, linkIndex) => <li key={linkIndex}>
                    <a href={link.href} {...newTab(link.href)} className="art:inline-flex art:min-h-10 art:items-center art:gap-1 art:rounded-full art:text-muted-foreground art:transition-colors art:hover:text-foreground art:focus-visible:outline-2 art:focus-visible:outline-offset-4 art:focus-visible:outline-ring art:text-sm">
                      {link.label}
                    </a>
                  </li>)}
                </ul>
              </nav>)}
            </div>
          </div>
          <div className="art:flex art:flex-col art:gap-4 art:border-t art:border-border art:py-5 art:@min-[1024px]/artemis:flex-row art:@min-[1024px]/artemis:items-center art:@min-[1024px]/artemis:justify-between">
            <div className="art:flex art:flex-wrap art:items-center art:gap-x-5 art:gap-y-2 art:text-xs art:text-muted-foreground">
              <p>
                {copy.legal}
              </p>
              <nav aria-label="Legal" className="art:flex art:flex-wrap art:gap-x-5">
                {copy.legalLinks.map((link, index) => <a key={index} href={link.href} {...newTab(link.href)} className="art:inline-flex art:min-h-10 art:items-center art:gap-1 art:rounded-full art:text-muted-foreground art:transition-colors art:hover:text-foreground art:focus-visible:outline-2 art:focus-visible:outline-offset-4 art:focus-visible:outline-ring art:text-xs">
                  {link.label}
                </a>)}
              </nav>
            </div>
            <div className="art:flex art:items-center art:justify-between art:gap-4">
              <span className="art:text-xs art:text-muted-foreground">
                {copy.note}
              </span>
              <nav aria-label="Social links" className="art:flex art:gap-2">
                {social.map((link, index) => {
                  const Icon = link.icon;
                  return <a key={index} href={link.href} {...newTab(link.href)} aria-label={link.label} title={link.label} className="art:grid art:size-10 art:place-items-center art:rounded-full art:bg-muted art:text-muted-foreground art:transition-colors art:hover:text-foreground art:focus-visible:outline-2 art:focus-visible:outline-offset-2 art:focus-visible:outline-ring">
                    <span aria-hidden="true">
                      {Icon ? <Icon className="art:size-4"/> : SOCIAL_ICONS[index % SOCIAL_ICONS.length]}
                    </span>
                  </a>;
                })}
              </nav>
            </div>
          </div>
        </motion.div>
      </footer>
    </MotionConfig>);
}
